const request = $input.first().json ?? {};
const headers = request.headers ?? {};
if (String(headers['x-visao360-test-mode'] ?? '').toUpperCase() !== 'OFFLINE_EVAL') throw new Error('Consulta permitida somente em OFFLINE_EVAL');
const query = request.query ?? {};
const tenantId = String(query.tenant_id ?? 'tenant-demo').trim();
const subjectRef = String(query.subject_ref ?? 'cust-demo-001').trim();
if (!tenantId || !subjectRef || tenantId.length > 120 || subjectRef.length > 160) throw new Error('Parâmetros de consulta inválidos');
return [{ json: { tenant_id: tenantId, subject_ref: subjectRef, execution_mode: 'OFFLINE_EVAL' } }];

const row = $input.first().json;
if (!row.state_id) return [{ json: { available: false, execution_mode: 'OFFLINE_EVAL', tenant_id: row.requested_tenant_id, subject_ref: row.requested_subject_ref, read_only: true } }];
const snapshot = typeof row.snapshot === 'string' ? JSON.parse(row.snapshot) : row.snapshot;
return [{ json: { available: true, execution_mode: 'OFFLINE_EVAL', read_only: true, state_id: row.state_id, state_version: Number(row.state_version), event_id: row.event_id, correlation_id: row.correlation_id, state_hash: row.state_hash, overall_status: row.overall_status, generated_at: row.generated_at, snapshot } }];
